"""Project delivery package (FR-16): source, setup instructions, test and review reports, limitations."""

from __future__ import annotations

import json
import zipfile
from datetime import UTC, datetime
from pathlib import Path
from typing import TYPE_CHECKING

from sqlalchemy import select

from app.db import session_scope
from app.models import Artifact, Project, ReviewFinding, Task, TestRun

if TYPE_CHECKING:
    from app.orchestrator.context import RunContext

STANDARD_LIMITATIONS = [
    "Generated by AI agents. Passing tests show the behaviour they cover, not the absence of defects.",
    "Review findings come from an AI reviewer plus static analysis and are not a substitute for a security audit.",
    "Production deployment, secrets management and data migration are outside DevFlow's scope.",
]


def build_report(project_id: int) -> dict:
    """Assemble the delivery report from persisted records. Used for the package and the Delivery screen."""
    with session_scope() as db:
        project = db.get(Project, project_id)
        tasks = list(db.scalars(select(Task).where(Task.project_id == project_id).order_by(Task.order_index)))
        final = db.scalar(select(TestRun).where(TestRun.project_id == project_id, TestRun.kind == "final").order_by(TestRun.id.desc()))
        findings = list(db.scalars(select(ReviewFinding).where(ReviewFinding.project_id == project_id).order_by(ReviewFinding.id)))
        plan = project.plan or {}
        return {
            "project": {"id": project.id, "name": project.name, "status": project.status, "status_reason": project.status_reason,
                        "mode": project.mode, "template": project.template},
            "config": project.config_snapshot,
            "summary": plan.get("summary", ""),
            "acceptance_criteria": plan.get("acceptance_criteria", []),
            "assumptions": plan.get("assumptions", []),
            "tasks": [{"id": t.key, "title": t.title, "status": t.status, "debug_attempts": t.debug_attempts,
                       "evidence": t.evidence} for t in tasks],
            "final_tests": None if final is None else {
                "summary": final.summary, "passed": final.passed, "failed": final.failed, "errors": final.errors,
                "skipped": final.skipped, "success": final.success, "executor": final.executor, "isolated": final.isolated,
                "failures": final.failures, "checks": final.checks,
            },
            "open_findings": [_finding(f) for f in findings if f.status == "open"],
            "resolved_findings": [_finding(f) for f in findings if f.status == "resolved"],
            "limitations": _limitations(project, final, findings),
        }


def _finding(f: ReviewFinding) -> dict:
    return {"severity": f.severity, "category": f.category, "source": f.source, "file": f.file, "line": f.line,
            "description": f.description, "recommendation": f.recommendation, "round": f.round}


def _limitations(project: Project, final: TestRun | None, findings: list[ReviewFinding]) -> list[str]:
    items = []
    if project.status != "completed":
        items.append(f"Workflow ended as '{project.status}': {project.status_reason or 'see history'}")
    if final is not None and not final.isolated:
        items.append("Tests ran with the non-isolated local executor (no container sandbox).")
    open_ = [f for f in findings if f.status == "open" and f.severity not in ("info",)]
    if open_:
        items.append(f"{len(open_)} review finding(s) remain open; see the review section.")
    return items + STANDARD_LIMITATIONS


def render_markdown(report: dict) -> str:
    p = report["project"]
    lines = [f"# {p['name']} — DevFlow delivery report", "", f"**Status:** {p['status']}  ", f"**Reason:** {p['status_reason'] or '-'}  ",
             f"**Mode:** {p['mode']} · **Template:** {p['template']}", ""]
    if report["summary"]:
        lines += ["## Summary", "", report["summary"], ""]
    lines += ["## Setup", "", "```bash", "python -m venv .venv", "# Windows: .venv\\Scripts\\activate   macOS/Linux: source .venv/bin/activate",
              "pip install -r requirements.txt", "pytest", "uvicorn app.main:app --reload", "```", ""]
    lines += ["## Tasks", "", "| Task | Title | Status | Debug attempts |", "|---|---|---|---|"]
    lines += [f"| {t['id']} | {t['title']} | {t['status']} | {t['debug_attempts']} |" for t in report["tasks"]] or ["| - | - | - | - |"]
    lines.append("")
    ft = report["final_tests"]
    lines += ["## Final test results", ""]
    if ft:
        lines += [f"- Result: **{'pass' if ft['success'] else 'fail'}** — {ft['summary']}",
                  f"- Executor: {ft['executor']} ({'isolated container' if ft['isolated'] else 'not isolated'})"]
        lines += [f"- `{f['nodeid']}`: {f['message'][:200]}" for f in ft["failures"]]
    else:
        lines.append("No final test run was recorded.")
    lines.append("")
    if report["acceptance_criteria"]:
        lines += ["## Acceptance criteria", ""] + [f"- {c}" for c in report["acceptance_criteria"]] + [""]
    lines += ["## Open review findings", ""]
    lines += [f"- **{f['severity']}** [{f['category']}] `{f['file'] or '-'}:{f['line']}` — {f['description']} _Recommendation:_ {f['recommendation']}"
              for f in report["open_findings"]] or ["None."]
    lines += ["", "## Known limitations", ""] + [f"- {item}" for item in report["limitations"]]
    if report["assumptions"]:
        lines += ["", "## Assumptions", ""] + [f"- {a}" for a in report["assumptions"]]
    return "\n".join(lines) + "\n"


def build_package(ctx: RunContext, *, outcome: str, reason: str) -> Path:
    # Record the outcome first so the report reflects it.
    with session_scope() as db:
        project = db.get(Project, ctx.project_id)
        project.status = outcome
        project.status_reason = reason
    report = build_report(ctx.project_id)
    stamp = datetime.now(UTC).strftime("%Y%m%dT%H%M%SZ")
    target = ctx.settings.packages_dir / f"project-{ctx.project_id}-{stamp}.zip"
    with zipfile.ZipFile(target, "w", zipfile.ZIP_DEFLATED) as zf:
        for rel in ctx.workspace.list_files():
            zf.write(ctx.workspace.root / rel, f"source/{rel}")
        zf.writestr("DEVFLOW_REPORT.md", render_markdown(report))
        zf.writestr("devflow_manifest.json", json.dumps({**report, "commit": ctx.git.head(), "generated_at": stamp}, indent=2, default=str))
    with session_scope() as db:
        project = db.get(Project, ctx.project_id)
        project.package_path = str(target)
        db.add(Artifact(project_id=ctx.project_id, kind="package", path=target.name, action="package", size=target.stat().st_size, commit=ctx.git.head()))
    return target
